using System;using System.IO;using System.Linq;using V15Voice;
public static class Subtitle149ResultTests {public static void Main(string[] args){var d=SubtitleDocument.Load(args[0]);d.Validate();if(d.Cues.Count!=87||d.Pipeline!="v149-verified-1"||d.Audit.Elements("change").Count()!=2)throw new Exception("Unexpected production result metadata");string text=String.Join(" ",d.Cues.Select(c=>c.Text.Replace('\n',' ')));if(text.Contains("the the")||text.Contains("because he's he")||!d.Cues.Any(c=>c.Text.Replace('\n',' ').Contains("smelled like vomit"))||!d.Cues.Any(c=>c.Text.Replace('\n',' ').Contains("throws it"))||!d.Cues.Any(c=>c.Text.Replace('\n',' ').Contains("being gone")))throw new Exception("Reported regression remains");string root=Path.Combine(Path.GetTempPath(),"v149-result-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string media=Path.Combine(root,"Wild Night Out P1 - Mr Ballen New Episode.mp4");File.WriteAllText(media,"KEEP");string first=d.ExportBeside(media),second=d.ExportBeside(media);if(Path.GetFileName(first)!="Wild Night Out P1 - Mr Ballen New Episode.srt"||!second.EndsWith("_2.srt")||File.ReadAllText(media)!="KEEP")throw new Exception("Adjacent output preservation failed");d.Save(Path.Combine(root,"project.xml"));var restored=SubtitleDocument.Load(Path.Combine(root,"project.xml"));if(restored.ReviewCount!=d.ReviewCount||restored.Audit.Elements("change").Count()!=2)throw new Exception("Review metadata lost");foreach(string file in args.Skip(1))SubtitleDocument.Load(file).Validate();Console.WriteLine("PASS real video result: 87 cues, reported duplicates removed, protected phrases intact, timestamps valid, adjacent SRT filename/preservation and project round-trip");}}
